import { site } from "@/config/site";
import { cn } from "@/lib/utils";
import { logoDirections, type LogoShape } from "./logo-data";

interface LogoProps {
  /** compact = symbol and wordmark in one line, symbol = icon only. */
  variant?: "compact" | "symbol";
  /** light = for light backgrounds, dark = for navy backgrounds. */
  tone?: "light" | "dark";
  className?: string;
  /** Accessible name. Omit when the surrounding link already has a label. */
  title?: string;
}

/**
 * Inline SVG logo. The active direction is set in src/config/site.ts (logoDirection);
 * shapes are generated by brand/tools/build.py, so swapping the logo is a config change.
 */
export function Logo({ variant = "compact", tone = "light", className, title }: LogoProps) {
  const direction = logoDirections[site.logoDirection];
  const shape: LogoShape = direction[variant];
  const palette: Record<string, string> = direction.palettes[tone];
  return (
    <svg
      xmlns="http://www.w3.org/2000/svg"
      viewBox={`0 0 ${shape.width} ${shape.height}`}
      className={cn("block h-auto", className)}
      role={title ? "img" : undefined}
      aria-hidden={title ? undefined : true}
      aria-label={title}
      focusable="false"
    >
      {title ? <title>{title}</title> : null}
      {shape.paths.map((p, i) => (
        <path key={i} d={p.d} fill={palette[p.role] ?? palette.word} />
      ))}
    </svg>
  );
}
